            let activity = s.reference(task, "learner-task/activity")?;
            if crate::retrieval::supported(s, activity)? {
                for step in s.refs(activity, "activity/steps")? {
                    reserved.insert(s.reference(step, "step/content")?);
                }
            }
        }
    }
    Ok(reserved)
}
